const imagePromises=new Map();
function loadImage(key){if(!key)return Promise.resolve(null);const src=getImageSource(key);if(!src)return Promise.resolve(null);if(imagePromises.has(key))return imagePromises.get(key);const p=new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=()=>reject(Error('Unable to load '+key));i.src=src});imagePromises.set(key,p);return p}
function rgba(hex,opacity){const h=(hex||'#ffffff').replace('#','');const n=parseInt(h.length===3?h.split('').map(x=>x+x).join(''):h,16);return `rgba(${n>>16&255},${n>>8&255},${n&255},${opacity})`}
function roundRect(ctx,x,y,w,h,r){const R=Math.min(r,w/2,h/2);ctx.beginPath();ctx.moveTo(x+R,y);ctx.lineTo(x+w-R,y);ctx.quadraticCurveTo(x+w,y,x+w,y+R);ctx.lineTo(x+w,y+h-R);ctx.quadraticCurveTo(x+w,y+h,x+w-R,y+h);ctx.lineTo(x+R,y+h);ctx.quadraticCurveTo(x,y+h,x,y+h-R);ctx.lineTo(x,y+R);ctx.quadraticCurveTo(x,y,x+R,y);ctx.closePath()}
function coverGeometry(img,x,y,w,h,posX=50,posY=50,zoom=100){const naturalW=img.naturalWidth||img.width,naturalH=img.naturalHeight||img.height;let scale=Math.max(w/naturalW,h/naturalH)*(zoom/100);const drawW=naturalW*scale,drawH=naturalH*scale;const dx=x+(w-drawW)*(posX/100),dy=y+(h-drawH)*(posY/100);return {x:dx,y:dy,w:drawW,h:drawH,scale}}
