function measureWrapped(ctx,text,maxW,fontSize,weight='500',maxLines=999){const arr=[],words=String(text||'').replace(/\r/g,'').split(/\s+/).filter(Boolean);ctx.font=`${weight} ${fontSize}px Arial, sans-serif`;if(!words.length)return [];let line='';for(let word of words){if(ctx.measureText(word).width>maxW){if(line){arr.push(line);line=''}let part='';for(const ch of word){if(ctx.measureText(part+ch).width>maxW&&part){arr.push(part);part=ch}else part+=ch}line=part;continue}const trial=line?line+' '+word:word;if(ctx.measureText(trial).width>maxW&&line){arr.push(line);line=word}else line=trial}if(line)arr.push(line);return arr}
function fitBlock(ctx,text,maxWidth,maxHeight,{maxFont=34,minFont=18,weight='500',lineHeight=1.22}={}){for(let f=maxFont;f>=minFont;f--){const lines=measureWrapped(ctx,text,maxWidth,f,weight),lh=f*lineHeight;if(lines.length*lh<=maxHeight)return {font:f,lines,lineHeight:lh,overflow:false}}const lines=measureWrapped(ctx,text,maxWidth,minFont,weight),lh=minFont*lineHeight;return {font:minFont,lines,lineHeight:lh,overflow:lines.length*lh>maxHeight}}
