function textParagraph(ctx,value,x,y,maxW,maxH,options,parts,qa){const spec=fitBlock(ctx,value,maxW,maxH,options);const align=options?.align||'left';let py=y;for(const line of spec.lines){textLayer(ctx,line,x,py,spec.font,options?.color||'#f4f0ec',options?.weight||'500',align,spec.lineHeight,parts);py+=spec.lineHeight}if(spec.overflow)qa.push({status:'fail',text:`Rules text overflows at minimum ${spec.font}px. Shorten or restructure before printing.`});else if(spec.font<Math.max(22,(options?.maxFont||32)-7))qa.push({status:'warn',text:`Dense rules typography (${spec.font}px at 300 PPI). Inspect at actual size.`});return spec}
