ctx.fillStyle=a;ctx.fillRect(38,h*.675,w-76,3);ctx.lineWidth=2;ctx.strokeStyle=rgba(a,.55);ctx.beginPath();ctx.moveTo(38,h*.91);ctx.lineTo(w-38,h*.91);ctx.stroke();
