async function exportSVG(){try{const c=cur();const file=await buildEditableSVG(c,state.settings.previewBack);downloadBlob(file,cardFileName(c,state.settings.previewBack?'back':'editable-front','svg'));toast('Layered SVG exported. Text stays editable.')}catch(e){toast('SVG export failed: '+e.message,5000)}}
function csvText(cards){const cols=['id','module','family','title','subtitle','abilityTitle','cost','frequency','effect','flavor','rulesStatus','artStatus','layoutStatus','artKey','version','source','sourceUrl','notes'];const q=v=>'"'+String(v??'').replace(/"/g,'""').replace(/\r?\n/g,' ')+'"';return [cols.join(','),...cards.map(c=>cols.map(k=>q(c[k])).join(','))].join('\r\n')}
